#!/bin/sh
# Generated by FWShift: rows for the packet filter (and NAT) of a Phoenix Contact mGuard, added with gaiconfig.
# Read the report first: what is not written is listed there.
#
#   DRY_RUN=1 sh THIS_FILE            prints the gaiconfig calls; runs anywhere
#   sh THIS_FILE                      on the mGuard (SSH, as root or admin): adds the groups and rows
#   FWSHIFT_APPEND=yes sh THIS_FILE   also when the tables have rows: the new ones go after them
#
# Nothing is changed or deleted, and no interface, route or access to the mGuard is touched. Every call but the last
# writes with --silent; the last one reconfigures, and the rows take effect then. A call gaiconfig refuses stops the
# script: what was written before is stored but not active (the groups start with 'fws_', the rows' comments
# with the names of the rules); remove it in the web interface, or run the script again after fixing the cause.
set -u
DRY_RUN="${DRY_RUN:-}"
FWSHIFT_APPEND="${FWSHIFT_APPEND:-}"
fail() { printf 'FAILED: %s\n' "$*" >&2; exit 1; }
gc() {
  if [ -n "$DRY_RUN" ]; then printf 'gaiconfig' >&2; printf ' %s' "$@" >&2; printf '\n' >&2; return 0; fi
  gaiconfig "$@" >/dev/null || fail "gaiconfig $*"
}
rows() {
  if [ -n "$DRY_RUN" ]; then echo 0; return 0; fi
  gaiconfig --get-rowcount "$1" || fail "gaiconfig --get-rowcount $1"
}
named() {
  [ -z "$DRY_RUN" ] && gaiconfig --get "$1" 2>/dev/null | grep -F -q "NAME = \"$2\""
}
if [ -z "$DRY_RUN" ] && ! command -v gaiconfig >/dev/null 2>&1; then fail "gaiconfig not found: run this on the mGuard"; fi
for t in FW_INCOMING FW_OUTGOING; do
  n=$(rows "$t")
  if [ "$n" != 0 ] && [ "$FWSHIFT_APPEND" != yes ]; then
    fail "$t has $n rows, which the mGuard would check before the new ones; nothing was written (FWSHIFT_APPEND=yes adds after them)"
  fi
done
named FW_GROUP_IP fws_Blocked-Nets__IPv4_ && fail 'an IP group named fws_Blocked-Nets__IPv4_ exists; nothing was written'
named FW_GROUP_IP fws_Admin-Hosts__port2_ && fail 'an IP group named fws_Admin-Hosts__port2_ exists; nothing was written'
named FW_GROUP_IP fws_DMZ-Servers && fail 'an IP group named fws_DMZ-Servers exists; nothing was written'
named FW_GROUP_IP fws_Admin-Hosts__port1_ && fail 'an IP group named fws_Admin-Hosts__port1_ exists; nothing was written'
named FW_GROUP_PORT fws_HTTP_S && fail 'a port group named fws_HTTP_S exists; nothing was written'
named FW_GROUP_PORT fws_Web-Group && fail 'a port group named fws_Web-Group exists; nothing was written'
named FW_GROUP_IP fws_Updates__IPv4_ && fail 'an IP group named fws_Updates__IPv4_ exists; nothing was written'

# FW_GROUP_IP
N=$(rows FW_GROUP_IP)
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_Blocked-Nets__IPv4_ --set .COMMENT 'FWShift: Blocked-Nets (IPv4)'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 198.51.100.0/24
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_Admin-Hosts__port2_ --set .COMMENT 'FWShift: Admin-Hosts (port2)'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.10.5.10/31
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_DMZ-Servers --set .COMMENT 'FWShift: DMZ-Servers'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.20.0.16-10.20.0.255
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_Admin-Hosts__port1_ --set .COMMENT 'FWShift: Admin-Hosts (port1)'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 192.0.2.50
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_Updates__IPv4_ --set .COMMENT 'FWShift: Updates (IPv4)'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP updates.example.com
N=$((N+1))

# FW_GROUP_PORT
N=$(rows FW_GROUP_PORT)
gc --silent --goto FW_GROUP_PORT --add-row --set .NAME fws_HTTP_S --set .COMMENT 'FWShift: HTTP+S'
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 80
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 443
N=$((N+1))
gc --silent --goto FW_GROUP_PORT --add-row --set .NAME fws_Web-Group --set .COMMENT 'FWShift: Web-Group'
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 80
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 443
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 8080
N=$((N+1))

# FW_INCOMING
N=$(rows FW_INCOMING)
gc --silent --goto FW_INCOMING --add-row --set .EXT_IF ext1 --set .PROTO all --set .FROM_IP 0.0.0.0/32 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF DROP --set .LOG yes --set .COMMENT 'BLOCK-BAD: known bad networks'
gc --silent --set-refname "FW_INCOMING.$N.FROM_IP" fws_Blocked-Nets__IPv4_
N=$((N+1))
gc --silent --goto FW_INCOMING --add-row --set .EXT_IF ext1 --set .PROTO tcp --set .FROM_IP 10.10.0.0/16 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT 0 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT LAN-2-INTERNET
gc --silent --set-refname "FW_INCOMING.$N.IN_PORT" fws_HTTP_S
N=$((N+1))
gc --silent --goto FW_INCOMING --add-row --set .EXT_IF ext1 --set .PROTO tcp --set .FROM_IP 0.0.0.0/32 --set .FROM_PORT any --set .IN_IP 10.10.0.0/16 --set .IN_PORT 0 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT SERVER-SYNC
gc --silent --set-refname "FW_INCOMING.$N.FROM_IP" fws_DMZ-Servers
gc --silent --set-refname "FW_INCOMING.$N.IN_PORT" fws_Web-Group
N=$((N+1))
gc --silent --goto FW_INCOMING --add-row --set .EXT_IF ext1 --set .PROTO tcp --set .FROM_IP 10.10.0.0/16 --set .FROM_PORT any --set .IN_IP 0.0.0.0/32 --set .IN_PORT 0 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT 'SERVER-SYNC (back)'
gc --silent --set-refname "FW_INCOMING.$N.IN_IP" fws_DMZ-Servers
gc --silent --set-refname "FW_INCOMING.$N.IN_PORT" fws_Web-Group
N=$((N+1))
gc --silent --goto FW_INCOMING --add-row --set .EXT_IF ext1 --set .PROTO icmp --set .FROM_IP 10.10.0.0/16 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT PING-ALL
N=$((N+1))
gc --silent --goto FW_INCOMING --add-row --set .EXT_IF ext1 --set .PROTO tcp --set .FROM_IP 0.0.0.0/32 --set .FROM_PORT any --set .IN_IP 0.0.0.0/32 --set .IN_PORT 0 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT UPDATES
gc --silent --set-refname "FW_INCOMING.$N.FROM_IP" fws_DMZ-Servers
gc --silent --set-refname "FW_INCOMING.$N.IN_IP" fws_Updates__IPv4_
gc --silent --set-refname "FW_INCOMING.$N.IN_PORT" fws_HTTP_S
N=$((N+1))
gc --silent --goto FW_INCOMING --add-row --set .EXT_IF ext1 --set .PROTO all --set .FROM_IP 10.10.0.0/16 --set .FROM_PORT any --set .IN_IP 0.0.0.0/32 --set .IN_PORT any --set .TARGET_REF REJECT --set .LOG yes --set .COMMENT DENY-LAN-DMZ
gc --silent --set-refname "FW_INCOMING.$N.IN_IP" fws_DMZ-Servers
N=$((N+1))
gc --silent --goto FW_INCOMING --add-row --set .EXT_IF ext1 --set .PROTO gre --set .FROM_IP 10.10.0.0/16 --set .FROM_PORT any --set .IN_IP 10.20.0.25 --set .IN_PORT any --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT GRE-LAB
N=$((N+1))
gc --silent --goto FW_INCOMING --add-row --set .EXT_IF ext1 --set .PROTO all --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF DROP --set .LOG yes --set .COMMENT BLOCKALL
N=$((N+1))

# FW_OUTGOING
N=$(rows FW_OUTGOING)
gc --silent --goto FW_OUTGOING --add-row --set .PROTO all --set .FROM_IP 0.0.0.0/32 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF DROP --set .LOG yes --set .COMMENT 'BLOCK-BAD: known bad networks'
gc --silent --set-refname "FW_OUTGOING.$N.FROM_IP" fws_Blocked-Nets__IPv4_
N=$((N+1))
gc --silent --goto FW_OUTGOING --add-row --set .PROTO tcp --set .FROM_IP 10.10.0.0/16 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT 0 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT LAN-2-INTERNET
gc --silent --set-refname "FW_OUTGOING.$N.IN_PORT" fws_HTTP_S
N=$((N+1))
gc --silent --goto FW_OUTGOING --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/32 --set .FROM_PORT any --set .IN_IP 10.10.0.0/16 --set .IN_PORT 0 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT SERVER-SYNC
gc --silent --set-refname "FW_OUTGOING.$N.FROM_IP" fws_DMZ-Servers
gc --silent --set-refname "FW_OUTGOING.$N.IN_PORT" fws_Web-Group
N=$((N+1))
gc --silent --goto FW_OUTGOING --add-row --set .PROTO tcp --set .FROM_IP 10.10.0.0/16 --set .FROM_PORT any --set .IN_IP 0.0.0.0/32 --set .IN_PORT 0 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT 'SERVER-SYNC (back)'
gc --silent --set-refname "FW_OUTGOING.$N.IN_IP" fws_DMZ-Servers
gc --silent --set-refname "FW_OUTGOING.$N.IN_PORT" fws_Web-Group
N=$((N+1))
gc --silent --goto FW_OUTGOING --add-row --set .PROTO icmp --set .FROM_IP 10.10.0.0/16 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT PING-ALL
N=$((N+1))
gc --silent --goto FW_OUTGOING --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/32 --set .FROM_PORT any --set .IN_IP 0.0.0.0/32 --set .IN_PORT 0 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT UPDATES
gc --silent --set-refname "FW_OUTGOING.$N.FROM_IP" fws_DMZ-Servers
gc --silent --set-refname "FW_OUTGOING.$N.IN_IP" fws_Updates__IPv4_
gc --silent --set-refname "FW_OUTGOING.$N.IN_PORT" fws_HTTP_S
N=$((N+1))
gc --silent --goto FW_OUTGOING --add-row --set .PROTO all --set .FROM_IP 10.10.0.0/16 --set .FROM_PORT any --set .IN_IP 0.0.0.0/32 --set .IN_PORT any --set .TARGET_REF REJECT --set .LOG yes --set .COMMENT DENY-LAN-DMZ
gc --silent --set-refname "FW_OUTGOING.$N.IN_IP" fws_DMZ-Servers
N=$((N+1))
gc --silent --goto FW_OUTGOING --add-row --set .PROTO gre --set .FROM_IP 10.10.0.0/16 --set .FROM_PORT any --set .IN_IP 10.20.0.25 --set .IN_PORT any --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT GRE-LAB
N=$((N+1))
gc --goto FW_OUTGOING --add-row --set .PROTO all --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF DROP --set .LOG yes --set .COMMENT BLOCKALL
N=$((N+1))

if [ -z "$DRY_RUN" ]; then
  for v in FW_INCOMING_GLOBAL FW_OUTGOING_GLOBAL; do
    g=$(gaiconfig --get "$v" 2>/dev/null || true)
    [ "$g" = rules ] || printf 'NOTE: %s is %s: the rows take effect only with "Use the firewall ruleset below" (rules)\n' "$v" "$g" >&2
  done
fi
echo 'Done. Check the tables in the web interface (Network Security >> Packet Filter, Network >> NAT).' >&2
